<template>
 <main class="bargain-statistics"><header class="heading"><div><h2>砍价活动统计 <small v-if="head">#{{ head.id }} · {{ head.title }}</small></h2><p class="hint">活动参与与已支付主订单分别统计；这里只读取历史，不改变砍价、订单或退款状态。</p></div><template v-for="control in controls" :key="control.key"><button v-if="session.allowed.value" type="button" @click="control.back">{{ session.has('activity.view') ? '返回活动列表' : '选择其他活动' }}</button><button v-if="session.allowed.value && id" type="button" @click="control.refresh">刷新统计</button></template></header>
 <el-alert v-if="!session.allowed.value" title="当前账号没有砍价统计查看权限" type="warning" :closable="false" />
 <template v-else-if="!id"><div class="chooser" v-for="control in controls" :key="control.key"><label>活动ID<input aria-label="砍价统计活动ID" :value="idInput" inputmode="numeric" @input="control.id(($event.target as HTMLInputElement).value)" @keyup.enter="control.open" /></label><button type="button" @click="control.open">打开统计</button><p v-if="idError" role="alert" class="bad">{{ idError }}</p></div></template>
 <template v-else><p v-if="headError" role="alert" class="bad">{{ headError }} <button v-for="control in controls" :key="control.key" type="button" @click="control.head">重试活动汇总</button></p><p v-if="headLoading" role="status">正在读取活动汇总…</p><el-alert v-if="head?.activity_deleted" title="活动已删除，仍保留历史统计" type="info" :closable="false" />
 <div class="cards"><article v-for="card in cards" :key="card.label"><p>{{ card.label }}</p><strong>{{ card.value }}</strong></article></div><p class="hint">次数按记录统计，非去重人数。可购买数按记录达到购买条件的历史状态统计；已创建订单记录 {{ head?.ordered_count ?? '—' }} 条。支付主订单含后续退款及删除历史，毛额不代表净收入；支付转化率 {{ head?.pay_rate ?? '—' }}%，按旧两段截断口径计算。</p>
 <div class="tabs" role="tablist" aria-label="砍价统计内容" v-for="control in controls" :key="control.key"><button type="button" role="tab" :aria-selected="tab==='records'" @click="control.records">活动参与人</button><button type="button" role="tab" :aria-selected="tab==='orders'" @click="control.orders">活动订单</button></div>
 <div class="filters" v-for="control in controls" :key="control.key"><label>搜索<input aria-label="砍价统计搜索" :value="draftKeyword" :placeholder="tab==='records'?'参与用户昵称 / 电话 / UID':'订单号、用户或电话'" @input="control.keyword(($event.target as HTMLInputElement).value)" @keyup.enter="control.search" /></label><label v-if="tab==='orders'">订单状态<select aria-label="砍价统计订单状态" :value="draftOrderStatus" @change="control.status(($event.target as HTMLSelectElement).value)"><option value="">全部状态</option><option value="0">未支付（此页无数据）</option><option value="1">待发货</option><option value="2">待收货 / 待核销</option><option value="3">待评价</option><option value="4">已完成</option><option value="5">待核销</option></select></label><div class="actions"><button type="button" @click="control.search">查询统计列表</button><button type="button" @click="control.reset">重置筛选</button></div></div>
 <p v-if="filterError" role="alert" class="bad">{{ filterError }}</p><p v-if="listError" role="alert" class="bad">{{ listError }} <button v-for="control in controls" :key="control.key" type="button" @click="control.retry">重试统计列表</button></p>
 <BargainRecordTable v-if="tab==='records'" :rows="records" :loading="listLoading" :enabled="session.allowed.value" :source-current="recordLease" @helpers="showHelpers" />
 <div v-else class="table-scroll"><p v-if="listLoading" role="status">正在读取已支付主订单…</p><table aria-label="砍价活动订单"><thead><tr><th>业务订单号</th><th>用户</th><th>订单状态</th><th>支付毛额（元）</th><th>商品数</th><th>下单时间</th><th>支付时间</th></tr></thead><tbody><tr v-for="entry in orderEntries" :key="entry.key"><td><button v-if="entry.available" type="button" @click="entry.open">{{ entry.row.order_id }}</button><span v-else>{{ entry.row.order_id || '历史订单身份不可核对' }}</span><small v-if="entry.row.deleted">已删除，仅保留历史</small></td><td>{{ entry.row.real_name }}<small>{{ entry.row.nickname }} / UID {{ entry.row.uid }}</small><small>{{ entry.row.user_phone }}</small></td><td>{{ entry.row.status }}<small>原状态 {{ entry.row.status_raw }} / 退款 {{ entry.row.refund_status }}</small><small v-if="entry.row.issues.length" class="bad">{{ entry.row.issues.join('；') }}</small></td><td>{{ entry.row.pay_price }}</td><td>{{ entry.row.total_num }}</td><td>{{ time(entry.row.add_time) }}</td><td>{{ time(entry.row.pay_time) }}</td></tr></tbody></table><p v-if="!listLoading && !orders.length && !listError" class="empty">暂无已支付主订单</p><p class="hint">列表与总数均统计已支付的砍价主订单，拆单后的子订单不会重复计入；未支付筛选为空。</p></div>
 <nav v-if="!listLoading && !listError" class="pager" aria-label="砍价统计分页"><span>第 {{ page }} 页 · 共 {{ count }} 条</span><template v-for="control in controls" :key="control.key"><button type="button" :disabled="page<=1" @click="control.previous">上一页</button><button type="button" :disabled="page*15>=count || page>=667" @click="control.next">下一页</button></template></nav></template>
 <BargainHelpers v-if="helpersVisible && id" v-model="helpersVisible" :source-current="helperLease" :record-id="helperRecord" :activity-id="id" />
 </main>
</template>
<script setup lang="ts">
import {computed,ref} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import BargainRecordTable from './BargainRecordTable.vue';
import BargainHelpers from './BargainHelpers.vue';
import {apiBargainStatisticsHead,apiBargainStatisticsRecords,apiBargainStatisticsOrders,bargainReadId,bargainReadError,bargainOrderAvailable,type BargainRecord,type BargainOrder,type BargainHead} from '@/api/bargainRecords';
import {useBargainReadSession,bargainReadTime as time} from './bargainReadSession';
const route=useRoute(),router=useRouter(),id=computed(()=>bargainReadId(route.params.id)),idInput=ref(''),idError=ref(''),head=ref<BargainHead|null>(null),headLoading=ref(false),headError=ref('');
const tab=ref<'records'|'orders'>('records'),records=ref<BargainRecord[]>([]),orders=ref<BargainOrder[]>([]),listLoading=ref(false),listError=ref(''),filterError=ref(''),page=ref(1),count=ref(0),draftKeyword=ref(''),draftOrderStatus=ref(''),intent=ref(0),helpersVisible=ref(false),helperRecord=ref(0),helperLease=ref<()=>boolean>(()=>false);
let recordsQuery={keyword:''},ordersQuery:{keyword:string;status:''|0|1|2|3|4|5}={keyword:'',status:''};
function filters(){draftKeyword.value=draftOrderStatus.value='';recordsQuery={keyword:''};ordersQuery={keyword:'',status:''};intent.value++;}
function discard(){head.value=null;records.value=[];orders.value=[];headLoading.value=listLoading.value=false;headError.value=listError.value=filterError.value=idError.value='';page.value=1;count.value=0;helpersVisible.value=false;helperRecord.value=0;tab.value='records';filters();}
const session=useBargainReadSession(()=> 'bargain_statistics.view',()=>route.fullPath,discard,reload);
const cards=computed(()=>[{label:'帮砍记录次数',value:head.value?.people_count??'—'},{label:'好友帮砍次数',value:head.value?.spread_count??'—'},{label:'发起记录数',value:head.value?.start_count??'—'},{label:'可购买记录数',value:head.value?.success_count??'—'},{label:'支付主订单毛额（元）',value:head.value?.pay_price??'—'},{label:'支付主订单数',value:head.value?.pay_count??'—'}]);
function reload(){if(id.value){void loadHead();void loadList(1);}}
async function loadHead(){if(!id.value)return;const job=session.begin('head');if(!job)return;const activity=id.value;head.value=null;headLoading.value=true;headError.value='';try{const result=await apiBargainStatisticsHead(activity,job.signal);if(job.current())head.value=result;}catch(reason){if(job.current())headError.value=bargainReadError(reason,'活动汇总读取失败');}finally{if(job.current())headLoading.value=false;job.finish();}}
async function loadList(target=page.value){if(!id.value||!Number.isSafeInteger(target)||target<1||target>667)return;const job=session.begin('list');if(!job)return;const activity=id.value,selected=tab.value;intent.value++;records.value=[];orders.value=[];count.value=0;page.value=target;listLoading.value=true;listError.value='';helpersVisible.value=false;try{const result=selected==='records'?await apiBargainStatisticsRecords(activity,{...recordsQuery,page:target,limit:15},job.signal):await apiBargainStatisticsOrders(activity,{...ordersQuery,page:target,limit:15},job.signal);if(job.current()&&selected===tab.value){if(selected==='records')records.value=result.list as BargainRecord[];else orders.value=result.list as BargainOrder[];count.value=result.count;}}catch(reason){if(job.current())listError.value=bargainReadError(reason,'统计列表读取失败');}finally{if(job.current())listLoading.value=false;job.finish();}}
function search(){if(!session.allowed.value)return;try{const keyword=draftKeyword.value.trim();if([...keyword].length>100)throw Error('搜索内容不能超过100个字符');if(tab.value==='records')recordsQuery={keyword};else{if(!['','0','1','2','3','4','5'].includes(draftOrderStatus.value))throw Error('订单状态无效');ordersQuery={keyword,status:draftOrderStatus.value?Number(draftOrderStatus.value) as 0|1|2|3|4|5:''};}filterError.value='';void loadList(1);}catch(reason){filterError.value=bargainReadError(reason,'筛选无效');}}
function changeTab(value:'records'|'orders'){session.cancel('list');tab.value=value;filters();filterError.value='';helpersVisible.value=false;void loadList(1);}
function showHelpers(row:BargainRecord){if(!session.allowed.value||listLoading.value||!records.value.includes(row))return;const view=session.lease(),version=intent.value,source=JSON.stringify(row);helperRecord.value=row.id;helpersVisible.value=true;helperLease.value=()=>view.current()&&version===intent.value&&helpersVisible.value&&helperRecord.value===row.id&&records.value.includes(row)&&JSON.stringify(row)===source&&!listLoading.value;}
const recordLease=computed(()=>{const view=session.lease(),version=intent.value;return()=>view.current()&&version===intent.value&&!listLoading.value;});
const controls=computed(()=>{const view=session.lease(),version=intent.value,current=()=>view.current()&&version===intent.value;const input=(change:()=>void)=>{if(view.current()){change();helpersVisible.value=false;intent.value++;}};return [{key:view.key,back:()=>{if(current())void router.push(session.has('activity.view')?'/activity?tab=bargain':'/activity/bargain-statistics');},keyword:(v:string)=>input(()=>draftKeyword.value=v),status:(v:string)=>input(()=>draftOrderStatus.value=v),id:(v:string)=>input(()=>idInput.value=v),open:()=>{if(!current())return;const target=bargainReadId(idInput.value.trim());if(!target){idError.value='请输入有效砍价活动ID';return;}idError.value='';void router.push('/activity/bargain-statistics/'+target);},search:()=>{if(current())search();},reset:()=>{if(current()){filters();filterError.value='';void loadList(1);}},records:()=>{if(current())changeTab('records');},orders:()=>{if(current())changeTab('orders');},refresh:()=>{if(current())reload();},head:()=>{if(current())void loadHead();},retry:()=>{if(current())void loadList(page.value);},previous:()=>{if(current()&&!listLoading.value&&page.value>1)void loadList(page.value-1);},next:()=>{if(current()&&!listLoading.value&&page.value*15<count.value)void loadList(page.value+1);}}];});
const orderEntries=computed(()=>{const view=session.lease(),version=intent.value;return orders.value.map(row=>{const snapshot=JSON.stringify(row),valid=()=>view.current()&&version===intent.value&&!listLoading.value&&tab.value==='orders'&&orders.value.includes(row)&&JSON.stringify(row)===snapshot&&session.has('order.view')&&bargainOrderAvailable(row);return {key:view.key+':'+version+':'+row.id,row,available:valid(),open:()=>{if(valid())void router.push('/order/'+encodeURIComponent(row.order_id));}};});});
</script>
<style scoped>
.bargain-statistics{min-width:0}.heading,.actions,.pager,.tabs{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.heading h2{margin:0;font-size:20px}.heading small{font-weight:400;font-size:14px;overflow-wrap:anywhere}.hint{color:#747b87;font-size:12px;line-height:1.7;overflow-wrap:anywhere}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:16px 0}.cards article{padding:16px;border:1px solid #e5e7eb;background:#fff;border-radius:6px}.cards p{margin:0 0 10px;font-size:12px;color:#747b87}.cards strong{font-size:23px;overflow-wrap:anywhere}.tabs{justify-content:flex-start;margin-top:20px}.tabs [aria-selected=true]{border-color:#409eff;color:#fff;background:#409eff}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:18px 0}.filters label,.chooser label{display:grid;gap:6px;font-size:13px;flex:1 1 180px;min-width:0}.filters input,.filters select,.chooser input{box-sizing:border-box;width:100%;min-width:0;border:1px solid #dcdfe6;border-radius:4px;padding:8px;background:#fff;font:inherit}button{font:inherit;padding:7px 11px;border:1px solid #dcdfe6;background:#fff;border-radius:4px;color:#356ac3;cursor:pointer}button:disabled{opacity:.5;cursor:default}.table-scroll{overflow-x:auto;max-width:100%}table{width:100%;min-width:1080px;border-collapse:collapse;font-size:13px;background:#fff}th,td{border:1px solid #e5e7eb;padding:12px;text-align:left;vertical-align:top}th{white-space:nowrap}td small{display:block;font-size:12px;color:#747b87;line-height:1.6}.bad{color:#c45656;overflow-wrap:anywhere}.pager{justify-content:flex-end;margin:18px 0;font-size:13px}.chooser{display:flex;align-items:end;flex-wrap:wrap;gap:12px;max-width:480px;margin-top:18px}.chooser p{flex-basis:100%}.empty{padding:24px;text-align:center;color:#909399}@media(max-width:650px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.cards article{padding:12px}.cards strong{font-size:19px}.filters{display:grid;grid-template-columns:minmax(0,1fr)}.pager{justify-content:center}}
</style>
